export interface CreatePermitRequest {
  /** Unique identifier of the work site where permit is required */
  workSiteId: string;
  /** ISO 8601 date string — permit validity start */
  startDate: string;
  /** ISO 8601 date string — permit validity end */
  endDate: string;
  /** Risk classification — drives approval routing */
  hazardLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  /** Employee ID of the supervising officer */
  supervisorId: string;
}

/**
 * Response from POST /api/rc_permit/createPermit.
 * permitId follows the PTW-{uuid} format generated by the REST backend.
 */
export interface PermitResponse {
  permitId: string;
  status: PermitStatus;
  workSiteId: string;
  startDate: string;
  endDate: string;
  hazardLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  supervisorId: string;
  createdAt: string;
}

/**
 * Permit status lifecycle — used in detail views and list filtering.
 */
export type PermitStatus =
  | 'DRAFT'
  | 'PENDING_APPROVAL'
  | 'APPROVED'
  | 'ACTIVE'
  | 'SUSPENDED'
  | 'CLOSED'
  | 'CANCELLED';

export interface PermitDetails extends PermitResponse {
  /** Safety conditions that must be met during the permit period */
  conditions: PermitCondition[];
  /** Audit history of status changes */
  history: PermitHistoryEntry[];
}

export interface PermitCondition {
  conditionId: string;
  description: string;
  mandatory: boolean;
  verified: boolean;
}

export interface PermitHistoryEntry {
  timestamp: string;
  fromStatus: PermitStatus;
  toStatus: PermitStatus;
  changedBy: string;
  notes?: string;
}

export interface PermitTypeListResponse {
  permitTypes: PermitTypeCode[];
}

export type PermitTypeCode =
  | 'HOT_WORK'
  | 'CONFINED_SPACE'
  | 'ELECTRICAL_ISOLATION'
  | 'WORK_AT_HEIGHT'
  | 'EXCAVATION'
  | 'RADIATION';

export interface WorkOrderResponse {
  workOrderId: string;
  title: string;
  description: string;
  priority: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  assignedTo: string;
  workSiteId: string;
  estimatedHours: number;
  status: 'OPEN' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
  createdAt: string;
  updatedAt: string;
}

export interface LoginFormValue {
  username: string;
  password: string;
  rememberMe: boolean;
}

export interface LoginResponse {
  accessToken: string;
  expiresIn: number;
  user: {
    username: string;
    role: 'operator' | 'admin' | 'supervisor';
    displayName: string;
  };
}
